widgets_values:
.banner {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 0;
    bottom: 0;
    left: 40%;
    right: 0;
    margin: 0;
    color:#FFF2BF;
    overflow: hidden;
    /*font-family: song;*/
}
.banner::after {
    content: '';
    position: absolute;
    width: 100%;
    left: -10%;
    top: -500px;
    font-size: 30px;
    letter-spacing: 50px;
    line-height: 100px;
    opacity:0.1;
    transform: rotate(-30deg);
    font-family: song;
    font-weight: lighter;
    
}

.block {
    flex: 10;
    border-radius: 200px;
    display: flex;
    align-items: lighter;
    padding: 10px 20px;
}

h1 {
    font-size: 60px;
    font-weight: bolder;
    font-family: song;
}

h3 {
    font-size: 42px;
    margin: -20px 20px;
    font-family: song;
}

h4 {
    font-size: 42px;
    font-family: song;
    font-weight: lighter;
    margin: 20px;
    border: solid 4px currentColor;
    display: flex;
    width: 60px;
    height: 60px;
    justify-content: center;
    align-items: center;
    border-radius: 100%;
}


.bar {
    height: 60px;
    display: flex;
    background: #fff1;
    
}

.bar .item {
    display: flex;
    align-items: center;
    padding: 10px 20px;
    width: 400px;
}

.bar h2.item {
    font-size: 40px;
    font-weight: bolder;
    font-family: song;
}

.gap {
    width: 100px;
}

.f1 {
    flex: 1;
}


* {
    font-family: Arial;
  }


  .startPage {
    position: absolute;
    top: 5;
    left:10%;
    bottom: 0;
    width:auto;
    z-index: 0;
    transition: transform 0.3s ease;
    align-items: center;
    justify-content: center;
  }

  .startPage:hover {
    transform: translateY(-1%);
  }

  .hoverContainer {
    background: gray;
    border-radius: 10px;
    padding:20px;
    display: flex;
    flex-direction: row;
    margin: 10px auto;
    position: center;
    align-items: center;
  }

  .header {
    padding-bottom: 24px;
    margin-bottom: 24px;
    border-bottom: 1px solid #3e3e3e;
    width: 200%;
    height: 72px;
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  .header_discrip {
    font-size: 21px;
    font-weight: 200;
    
    color: #6f6f6f;
  }

  .size-smallButton {
    font-size: 21px;
    border-radius: 12px;
    height: 48px;
    min-width: 48px;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    cursor: pointer;
  }

  .style-input {
    background: #2a2a2b;
    padding: 12px;

    transition: background 0.3s;
  }

  .style-input:hover {
    background: #3b3b3c;
  }
a:not(:first-child) {
      margin-left:8px;}
  a {
    color: #b6b6b7;
  }

  a:hover,
  a:hover .header_discrip {
    color: #dddddd !important;
  }
